;// TempMail Private v1.0.8：私有域名随机邮箱 —— Cloudflare Worker + KV + Email Routing
// 单文件部署：前端页面直接嵌在 INDEX_HTML 里（由 build.js 从 src/index.html 生成），
// 部署时只需上传这一个 _worker.js，再绑定一个 KV（MAILBOXES），不用 wrangler 也能部署。
// 域名在 MAIL_DOMAIN 修改（同时改页面里的 DOMAIN 常量）。
// 正文解析：Cloudflare 的 ForwardableEmailMessage 没有 text()/html() 方法，
// 必须读 message.raw 再用 PostalMime 解析 MIME（bundle 由 build.js 拼在文件开头）。
const WORKER_VERSION = '1.0.8';
const MAIL_DOMAIN = 'mbds.kdns.fr';

// 寿命选项：秒数，0 = 永久
const TTL_OPTIONS = { '10m': 600, '1h': 3600, '1d': 86400, '7d': 604800, 'forever': 0 };
const MAX_MSGS_PER_BOX = 50;      // 每个邮箱最多存 50 封
const MAX_TEXT_CHARS = 200000;    // 正文纯文本截断
const MAX_HTML_CHARS = 500000;    // 正文 HTML 截断
const MAX_ATTACHMENT_BYTES = 10 * 1024 * 1024;  // 单个附件上限 10MB
const MAX_ATTACHMENTS_TOTAL = 12 * 1024 * 1024; // 每封邮件附件总和上限 12MB
const CREATE_LIMIT_PER_HOUR = 20; // 每 IP 每小时最多建 20 个邮箱

const ADDRESS_RE = /^[a-z0-9][a-z0-9-]{0,63}$/;
const MSG_ID_RE = /^[0-9a-f]{16}$/;

const INDEX_HTML = "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>随机邮箱 · mbds.kdns.fr</title>\n<style>\n  * { box-sizing: border-box; }\n  body { margin: 0; font-family: system-ui, -apple-system, \"PingFang SC\", \"Microsoft YaHei\", sans-serif; background: #f1f5f9; color: #0f172a; }\n  .wrap { max-width: 720px; margin: 0 auto; padding: 20px 16px 40px; }\n  header { text-align: center; margin: 8px 0 20px; }\n  header h1 { font-size: 1.6rem; margin: 0 0 6px; }\n  header p { color: #64748b; margin: 0; font-size: 0.95rem; }\n  .card { background: #fff; border-radius: 16px; padding: 20px; margin-bottom: 16px; box-shadow: 0 1px 3px rgba(15,23,42,.08); }\n  .label { font-size: 0.8rem; color: #64748b; margin-bottom: 8px; }\n  .ttl-row { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 14px; }\n  .ttl-btn { flex: 1; min-width: 64px; border: 1px solid #cbd5e1; background: #fff; color: #334155; border-radius: 10px; padding: 9px 6px; font-size: 0.9rem; cursor: pointer; }\n  .ttl-btn.active { background: #2563eb; border-color: #2563eb; color: #fff; font-weight: 600; }\n  .address { font-family: ui-monospace, \"SF Mono\", Menlo, Consolas, monospace; font-size: 1.05rem; font-weight: 700; word-break: break-all; padding: 14px; background: #f8fafc; border: 1px dashed #cbd5e1; border-radius: 12px; text-align: center; min-height: 52px; display: flex; align-items: center; justify-content: center; }\n  .address.empty { color: #94a3b8; font-weight: 400; font-size: 0.95rem; font-family: inherit; }\n  .expiry { text-align: center; font-size: 0.85rem; color: #64748b; margin-top: 8px; min-height: 1.2em; }\n  .expiry.soon { color: #dc2626; font-weight: 600; }\n  .btn-row { display: flex; gap: 10px; margin-top: 12px; }\n  button { border: none; border-radius: 12px; padding: 13px 10px; font-size: 1rem; font-weight: 600; cursor: pointer; }\n  button:disabled { opacity: .5; cursor: default; }\n  .btn-primary { background: #2563eb; color: #fff; flex: 1; }\n  .btn-primary:active { background: #1d4ed8; }\n  .btn-secondary { background: #e2e8f0; color: #0f172a; flex: 1; }\n  .btn-secondary:active { background: #cbd5e1; }\n  .btn-danger { background: #fee2e2; color: #b91c1c; flex: 1; }\n  .status { margin-top: 12px; font-size: 0.88rem; color: #64748b; text-align: center; min-height: 1.3em; }\n  .status.error { color: #dc2626; }\n  .status.ok { color: #16a34a; }\n  .box-item { border: 1px solid #e2e8f0; border-radius: 12px; padding: 10px 12px; margin-bottom: 8px; cursor: pointer; display: flex; justify-content: space-between; align-items: center; gap: 8px; }\n  .box-item.active { border-color: #2563eb; background: #eff6ff; }\n  .box-item.expired { opacity: .55; }\n  .box-item .addr { font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 0.88rem; word-break: break-all; }\n  .box-item .left { color: #64748b; font-size: 0.78rem; white-space: nowrap; }\n  .box-item .left.soon { color: #dc2626; font-weight: 600; }\n  .box-del { flex: none; background: none; border: none; color: #94a3b8; font-size: 1.1rem; padding: 2px 6px; cursor: pointer; }\n  .inbox-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px; }\n  .inbox-head h2 { font-size: 1.05rem; margin: 0; }\n  .inbox-head h2 span { color: #2563eb; }\n  .btn-small { flex: none; padding: 8px 14px; font-size: 0.88rem; border-radius: 10px; }\n  .inbox-tools { display: flex; gap: 8px; margin-bottom: 12px; }\n  .msg { border: 1px solid #e2e8f0; border-radius: 12px; padding: 12px 14px; margin-bottom: 10px; cursor: pointer; display: flex; align-items: flex-start; }\n  .msg:active { background: #f8fafc; }\n  .msg.unread { border-color: #93c5fd; background: #eff6ff; }\n  .msg-check { flex: none; width: 20px; height: 20px; margin: 2px 10px 0 0; cursor: pointer; accent-color: #2563eb; }\n  .msg-body { flex: 1; min-width: 0; }\n  .msg .from { font-weight: 600; font-size: 0.92rem; word-break: break-all; }\n  .msg .subject { color: #334155; font-size: 0.92rem; margin-top: 2px; word-break: break-all; }\n  .msg .time { color: #94a3b8; font-size: 0.78rem; margin-top: 4px; }\n  .empty-inbox { text-align: center; color: #94a3b8; padding: 28px 10px; line-height: 1.7; font-size: 0.92rem; }\n  .detail { border-top: 1px solid #e2e8f0; margin-top: 6px; padding-top: 16px; }\n  .detail h3 { font-size: 1rem; margin: 0 0 6px; word-break: break-all; }\n  .detail .meta { color: #64748b; font-size: 0.82rem; margin-bottom: 12px; word-break: break-all; }\n  .codes { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 14px; }\n  .code-chip { background: #fef3c7; border: 1px solid #fcd34d; border-radius: 10px; padding: 10px 14px; font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 1.3rem; font-weight: 700; letter-spacing: 2px; cursor: pointer; }\n  .code-chip small { display: block; font-family: inherit; font-size: 0.7rem; font-weight: 400; letter-spacing: 0; color: #92400e; text-align: center; }\n  .body-text { white-space: pre-wrap; word-break: break-word; font-size: 0.92rem; line-height: 1.7; color: #334155; background: #f8fafc; border-radius: 12px; padding: 14px; max-height: 400px; overflow: auto; }\n  .body-frame { width: 100%; height: 400px; border: 1px solid #e2e8f0; border-radius: 12px; }\n  .atts { margin-bottom: 14px; }\n  .att-item { border: 1px solid #e2e8f0; border-radius: 12px; padding: 12px; margin-bottom: 10px; background: #f8fafc; }\n  .att-img { max-width: 100%; border-radius: 8px; display: block; margin-bottom: 8px; }\n  .att-video { width: 100%; border-radius: 8px; display: block; margin-bottom: 8px; background: #000; }\n  .att-name { font-size: 0.9rem; font-weight: 600; word-break: break-all; }\n  .att-meta { font-size: 0.8rem; color: #64748b; margin-top: 2px; }\n  .att-link { display: inline-block; margin-top: 6px; font-size: 0.88rem; color: #2563eb; font-weight: 600; text-decoration: none; }\n  .update-banner { background: #fef3c7; border: 1px solid #f59e0b; color: #92400e; border-radius: 10px; padding: 10px 12px; margin-bottom: 12px; font-size: 0.88rem; display: none; }\n  .update-banner button { background: #f59e0b; color: #fff; border: none; border-radius: 8px; padding: 6px 12px; font-size: 0.85rem; font-weight: 600; cursor: pointer; margin-left: 8px; }\n  .detail-actions { display: flex; gap: 10px; margin-top: 12px; }\n  footer { text-align: center; color: #94a3b8; font-size: 0.82rem; line-height: 1.7; }\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <div class=\"update-banner\" id=\"updateBanner\">已发布新版本，刷新页面后生效。<button id=\"updateReloadBtn\">点此刷新</button></div>\n  <header>\n    <h1>📧 随机邮箱</h1>\n    <p>你的私有域名邮箱 · 点一下生成一个，验证码自动收在这里</p>\n  </header>\n\n  <div class=\"card\">\n    <div class=\"label\">新邮箱的寿命</div>\n    <div class=\"ttl-row\" id=\"ttlRow\">\n      <button class=\"ttl-btn\" data-ttl=\"10m\">10 分钟</button>\n      <button class=\"ttl-btn active\" data-ttl=\"1h\">1 小时</button>\n      <button class=\"ttl-btn\" data-ttl=\"1d\">1 天</button>\n      <button class=\"ttl-btn\" data-ttl=\"7d\">7 天</button>\n      <button class=\"ttl-btn\" data-ttl=\"forever\">永久</button>\n    </div>\n    <div class=\"label\">当前邮箱</div>\n    <div class=\"address empty\" id=\"addressBox\">正在生成…</div>\n    <div class=\"expiry\" id=\"expiryBox\"></div>\n    <div class=\"btn-row\">\n      <button class=\"btn-secondary\" id=\"copyBtn\" disabled>复制邮箱</button>\n      <button class=\"btn-primary\" id=\"genBtn\">生成新邮箱</button>\n    </div>\n    <div class=\"btn-row\">\n      <button class=\"btn-danger\" id=\"delBoxBtn\" disabled>删除这个邮箱</button>\n    </div>\n    <div class=\"status\" id=\"status\"></div>\n  </div>\n\n  <div class=\"card\" id=\"myBoxesCard\">\n    <div class=\"label\">我的邮箱</div>\n    <div id=\"boxList\"></div>\n  </div>\n\n  <div class=\"card\">\n    <div class=\"inbox-head\">\n      <h2>收件箱 <span id=\"msgCount\"></span></h2>\n      <button class=\"btn-secondary btn-small\" id=\"refreshBtn\">刷新</button>\n    </div>\n    <div class=\"inbox-tools\">\n      <button class=\"btn-secondary btn-small\" id=\"selectAllBtn\" disabled>全选</button>\n      <button class=\"btn-danger btn-small\" id=\"delSelectedBtn\" disabled>删除选中</button>\n    </div>\n    <div id=\"msgList\"><div class=\"empty-inbox\">暂无邮件<br>把上面的邮箱拿去注册，验证码会显示在这里</div></div>\n    <div id=\"detail\"></div>\n  </div>\n\n  <footer>临时邮箱到期后自动删除，连同里面的邮件一起删掉。<br>邮箱地址与访问口令只保存在你的浏览器里。<br>版本 v1.0.8</footer>\n</div>\n\n<script>\nconst $ = id => document.getElementById(id);\nconst LS_KEY = 'tempmail.private.v1';\nconst POLL_MS = 3000;\nconst POLL_FAST_MS = 2000; // 收件箱为空时（多半在等验证码）查得更勤\nconst TTL_LABELS = { '10m': '10 分钟', '1h': '1 小时', '1d': '1 天', '7d': '7 天', 'forever': '永久' };\nlet boxes = [];        // [{address, token, createdAt, expiresAt, expired}]\nlet current = null;    // 当前选中邮箱的 address\nlet selectedTtl = '1h';\nlet pollTimer = null;\nlet countdownTimer = null;\nlet loadingMsgs = false;\nlet seenIds = new Set();\nlet selectedIds = new Set();  // 勾选要删除的邮件 id\nlet lastMessages = [];        // 最近一次收件箱列表\n\nfunction setStatus(text, cls) {\n  const el = $('status');\n  el.textContent = text;\n  el.className = 'status' + (cls ? ' ' + cls : '');\n}\n\nasync function api(path, opts) {\n  const res = await fetch(path, opts);\n  if (res.status === 204) return null;\n  const text = await res.text();\n  let data = null;\n  try { data = JSON.parse(text); } catch (_) {}\n  if (!res.ok) {\n    const err = new Error((data && data.error) || ('请求失败 ' + res.status));\n    err.status = res.status;\n    throw err;\n  }\n  return data;\n}\n\nfunction saveBoxes() {\n  try { localStorage.setItem(LS_KEY, JSON.stringify(boxes)); } catch (_) {}\n}\nfunction loadBoxes() {\n  try {\n    const raw = localStorage.getItem(LS_KEY);\n    if (!raw) return [];\n    const arr = JSON.parse(raw);\n    return Array.isArray(arr) ? arr.filter(b => b && b.address && b.token) : [];\n  } catch (_) { return []; }\n}\n\nfunction currentBox() {\n  return boxes.find(b => b.address === current) || null;\n}\n\nfunction fmtLeft(expiresAt) {\n  if (!expiresAt) return '永久';\n  const ms = expiresAt - Date.now();\n  if (ms <= 0) return '已过期';\n  const s = Math.floor(ms / 1000);\n  if (s < 60) return s + ' 秒后过期';\n  const m = Math.floor(s / 60);\n  if (m < 60) return m + ' 分钟后过期';\n  const h = Math.floor(m / 60);\n  if (h < 24) return h + ' 小时后过期';\n  const d = Math.floor(h / 24);\n  return d + ' 天后过期';\n}\nfunction isSoon(expiresAt) {\n  return expiresAt && (expiresAt - Date.now() < 10 * 60 * 1000) && (expiresAt - Date.now() > 0);\n}\n\nfunction renderCurrent() {\n  const box = $('addressBox');\n  const b = currentBox();\n  if (b) {\n    box.textContent = b.address;\n    box.classList.remove('empty');\n    $('copyBtn').disabled = false;\n    $('delBoxBtn').disabled = false;\n  } else {\n    box.textContent = boxes.length ? '点下面的邮箱切换，或生成一个新邮箱' : '还没有邮箱，点下面按钮生成一个';\n    box.classList.add('empty');\n    $('copyBtn').disabled = true;\n    $('delBoxBtn').disabled = true;\n  }\n  renderExpiry();\n}\n\nfunction renderExpiry() {\n  const b = currentBox();\n  const el = $('expiryBox');\n  if (!b) { el.textContent = ''; el.className = 'expiry'; return; }\n  if (b.expired) { el.textContent = '这个邮箱已过期，邮件已删除'; el.className = 'expiry soon'; return; }\n  el.textContent = b.expiresAt ? ('剩余时间：' + fmtLeft(b.expiresAt)) : '永久邮箱，不会过期';\n  el.className = 'expiry' + (isSoon(b.expiresAt) ? ' soon' : '');\n}\n\nfunction renderBoxList() {\n  const wrap = $('boxList');\n  if (!boxes.length) {\n    wrap.innerHTML = '<div class=\"empty-inbox\" style=\"padding:12px\">还没有邮箱</div>';\n    return;\n  }\n  wrap.innerHTML = '';\n  boxes.forEach(b => {\n    const div = document.createElement('div');\n    div.className = 'box-item' + (b.address === current ? ' active' : '') + (b.expired ? ' expired' : '');\n    const left = document.createElement('div');\n    left.innerHTML = '<div class=\"addr\"></div>';\n    left.querySelector('.addr').textContent = b.address;\n    const right = document.createElement('div');\n    right.style.display = 'flex';\n    right.style.alignItems = 'center';\n    right.style.gap = '4px';\n    const span = document.createElement('span');\n    span.className = 'left' + (isSoon(b.expiresAt) ? ' soon' : '');\n    span.textContent = b.expired ? '已过期' : fmtLeft(b.expiresAt);\n    const del = document.createElement('button');\n    del.className = 'box-del';\n    del.textContent = '✕';\n    del.title = '从列表移除';\n    del.onclick = ev => { ev.stopPropagation(); removeBox(b.address, false); };\n    right.appendChild(span);\n    right.appendChild(del);\n    div.appendChild(left);\n    div.appendChild(right);\n    div.onclick = () => selectBox(b.address);\n    wrap.appendChild(div);\n  });\n}\n\nfunction renderAll() {\n  renderCurrent();\n  renderBoxList();\n}\n\nfunction selectBox(address) {\n  current = address;\n  seenIds = new Set();\n  selectedIds = new Set();\n  $('detail').innerHTML = '';\n  renderAll();\n  loadMessages();\n}\n\nfunction removeBox(address, serverDelete) {\n  boxes = boxes.filter(b => b.address !== address);\n  saveBoxes();\n  if (current === address) {\n    current = boxes.length ? boxes[0].address : null;\n    seenIds = new Set();\n    selectedIds = new Set();\n    $('detail').innerHTML = '';\n  }\n  renderAll();\n  if (current) loadMessages();\n  else { $('msgList').innerHTML = '<div class=\"empty-inbox\">暂无邮件<br>把上面的邮箱拿去注册，验证码会显示在这里</div>'; $('msgCount').textContent = ''; }\n}\n\nasync function generateMailbox() {\n  $('genBtn').disabled = true;\n  setStatus('正在生成新邮箱…');\n  try {\n    const mb = await api('/api/mailboxes', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ ttl: selectedTtl }),\n    });\n    boxes.unshift({ address: mb.address, token: mb.token, createdAt: mb.createdAt, expiresAt: mb.expiresAt });\n    saveBoxes();\n    selectBox(mb.address);\n    setStatus('新邮箱已生成（' + TTL_LABELS[selectedTtl] + '）', 'ok');\n  } catch (e) {\n    console.error(e);\n    setStatus(e.status === 429 ? '创建太频繁，请稍后再试' : ('生成失败：' + e.message), 'error');\n  } finally {\n    $('genBtn').disabled = false;\n  }\n}\n\nasync function loadMessages() {\n  const b = currentBox();\n  if (!b || b.expired || loadingMsgs) return;\n  loadingMsgs = true;\n  try {\n    const data = await api('/api/mailboxes/' + encodeURIComponent(b.address) + '/messages?token=' + encodeURIComponent(b.token));\n    renderMessages(data.messages || []);\n    // 收件箱为空时多半在等验证码，2 秒查一次；有邮件后回到 3 秒\n    const wantFast = (data.messages || []).length === 0;\n    if (wantFast && pollMs !== POLL_FAST_MS) restartPolling(POLL_FAST_MS);\n    if (!wantFast && pollMs !== POLL_MS) restartPolling(POLL_MS);\n    // 服务端可能纠正过期时间，同步一下\n    if (data.expiresAt !== undefined && data.expiresAt !== b.expiresAt) {\n      b.expiresAt = data.expiresAt;\n      saveBoxes();\n      renderExpiry();\n      renderBoxList();\n    }\n  } catch (e) {\n    console.error(e);\n    if (e.status === 410) {\n      b.expired = true;\n      saveBoxes();\n      renderAll();\n      $('msgList').innerHTML = '<div class=\"empty-inbox\">这个邮箱已过期，邮件已删除<br>可以生成一个新邮箱</div>';\n      $('msgCount').textContent = '';\n    } else if (e.status === 404) {\n      b.expired = true;\n      saveBoxes();\n      renderAll();\n      $('msgList').innerHTML = '<div class=\"empty-inbox\">这个邮箱不存在了（可能已在别处删除）</div>';\n    } else {\n      setStatus('收件箱刷新失败：' + e.message, 'error');\n    }\n  } finally {\n    loadingMsgs = false;\n  }\n}\n\nfunction fmtTime(iso) {\n  try {\n    const d = new Date(iso);\n    return d.toLocaleString('zh-CN', { hour12: false });\n  } catch (_) { return iso || ''; }\n}\n\nfunction fmtSize(n) {\n  if (n === undefined || n === null) return '';\n  if (n < 1024) return n + ' B';\n  if (n < 1024 * 1024) return (n / 1024).toFixed(1) + ' KB';\n  return (n / 1024 / 1024).toFixed(1) + ' MB';\n}\n\n// 解码 RFC 2047 编码字，如 =?UTF-8?B?5rWL6K+V6YKu5Lu2?= → 测试邮件。\n// 服务端 v1.0.1 起入库前已解码；这里再解一次是为了让修复前存下的旧邮件也能正常显示。\nfunction decodeRfc2047(str) {\n  if (!str || str.indexOf('=?') === -1) return str;\n  const cleaned = str.replace(/(\\?=\\s+)(?==\\?)/g, '?=');\n  return cleaned.replace(/=\\?([^?\\s]+)\\?([bBqQ])\\?([^?]*)\\?=/g, (m, charset, enc, text) => {\n    let bytes;\n    try {\n      if (enc.toUpperCase() === 'B') {\n        const bin = atob(text.replace(/\\s/g, ''));\n        bytes = new Uint8Array(bin.length);\n        for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);\n      } else {\n        const q = text.replace(/_/g, ' ');\n        const arr = [];\n        for (let i = 0; i < q.length; i++) {\n          if (q[i] === '=' && /^[0-9A-Fa-f]{2}$/.test(q.slice(i + 1, i + 3))) {\n            arr.push(parseInt(q.slice(i + 1, i + 3), 16));\n            i += 2;\n          } else {\n            arr.push(q.charCodeAt(i));\n          }\n        }\n        bytes = new Uint8Array(arr);\n      }\n      try {\n        return new TextDecoder(charset).decode(bytes);\n      } catch (_) {\n        return new TextDecoder('utf-8').decode(bytes);\n      }\n    } catch (_) {\n      return m;\n    }\n  });\n}\n\nfunction updateBulkTools() {\n  const total = lastMessages.length;\n  const n = selectedIds.size;\n  const allBtn = $('selectAllBtn');\n  const delBtn = $('delSelectedBtn');\n  allBtn.disabled = total === 0;\n  allBtn.textContent = total > 0 && n === total ? '取消全选' : '全选';\n  delBtn.disabled = n === 0;\n  delBtn.textContent = n > 0 ? '删除选中 (' + n + ')' : '删除选中';\n}\n\nfunction renderMessages(list) {\n  lastMessages = list;\n  $('msgCount').textContent = list.length ? '(' + list.length + ')' : '';\n  // 轮询刷新会重建列表，勾选状态存在 Set 里，顺便去掉已不存在的 id\n  const ids = new Set(list.map(m => m.id));\n  selectedIds = new Set([...selectedIds].filter(id => ids.has(id)));\n  const wrap = $('msgList');\n  if (!list.length) {\n    wrap.innerHTML = '<div class=\"empty-inbox\">暂无邮件<br>把上面的邮箱拿去注册，验证码会显示在这里</div>';\n    updateBulkTools();\n    return;\n  }\n  wrap.innerHTML = '';\n  list.forEach(m => {\n    const isNew = !seenIds.has(m.id);\n    const div = document.createElement('div');\n    div.className = 'msg' + (isNew ? ' unread' : '');\n    const check = document.createElement('input');\n    check.type = 'checkbox';\n    check.className = 'msg-check';\n    check.checked = selectedIds.has(m.id);\n    check.onclick = ev => {\n      ev.stopPropagation();\n      if (check.checked) selectedIds.add(m.id); else selectedIds.delete(m.id);\n      updateBulkTools();\n    };\n    const body = document.createElement('div');\n    body.className = 'msg-body';\n    body.innerHTML = '<div class=\"from\"></div><div class=\"subject\"></div><div class=\"time\"></div>';\n    body.querySelector('.from').textContent = decodeRfc2047(m.from) || '未知发件人';\n    body.querySelector('.subject').textContent = decodeRfc2047(m.subject) || '(无主题)';\n    body.querySelector('.time').textContent = fmtTime(m.createdAt) + (m.snippet ? ' · ' + m.snippet : '');\n    div.appendChild(check);\n    div.appendChild(body);\n    div.onclick = () => { seenIds.add(m.id); div.classList.remove('unread'); openMessage(m.id); };\n    wrap.appendChild(div);\n  });\n  updateBulkTools();\n}\n\nfunction extractCodes(text) {\n  if (!text) return [];\n  // 先去掉链接，避免把链接里的数字段（如验证链接 UUID 里的 7416、4511）误当成验证码\n  const clean = text.replace(/https?:\\/\\/\\S+/g, ' ');\n  const found = clean.match(/\\b\\d{4,8}\\b/g) || [];\n  return [...new Set(found)];\n}\n\nasync function openMessage(id) {\n  const b = currentBox();\n  if (!b) return;\n  const detail = $('detail');\n  detail.innerHTML = '<div class=\"detail\"><div class=\"status\">正在读取邮件…</div></div>';\n  try {\n    const m = await api('/api/mailboxes/' + encodeURIComponent(b.address) + '/messages/' + id + '?token=' + encodeURIComponent(b.token));\n    const subject = decodeRfc2047(m.subject);\n    const from = decodeRfc2047(m.from);\n    const codes = extractCodes((m.text || '') + '\\n' + (subject || ''));\n    let html = '<div class=\"detail\"><h3></h3><div class=\"meta\"></div>';\n    if (codes.length) {\n      html += '<div class=\"label\">验证码（点一下复制）</div><div class=\"codes\">' +\n        codes.map(c => '<div class=\"code-chip\" data-code=\"' + c + '\">' + c + '<small>点一下复制</small></div>').join('') +\n        '</div>';\n    }\n    if (m.text) {\n      html += '<div class=\"body-text\"></div>';\n    } else if (m.html) {\n      html += '<iframe class=\"body-frame\" sandbox></iframe>';\n    } else {\n      html += '<div class=\"body-text\">（这封邮件没有正文）</div>';\n    }\n    if (m.attachments && m.attachments.length) {\n      html += '<div class=\"label\" style=\"margin-top:14px\">附件（' + m.attachments.length + '）</div><div class=\"atts\" id=\"attList\"></div>';\n    }\n    if (m.skippedAttachments && m.skippedAttachments.length) {\n      html += '<div class=\"label\" style=\"margin-top:14px\">未保存的附件</div><div class=\"atts\" id=\"skipList\"></div>';\n    }\n    html += '<div class=\"detail-actions\"><button class=\"btn-secondary\" id=\"delMsgBtn\">删除这封邮件</button></div></div>';\n    detail.innerHTML = html;\n    detail.querySelector('h3').textContent = subject || '(无主题)';\n    detail.querySelector('.meta').textContent = (from || '') + ' · ' + fmtTime(m.createdAt);\n    if (m.text) detail.querySelector('.body-text').textContent = m.text;\n    if (!m.text && m.html) detail.querySelector('.body-frame').srcdoc = m.html;\n    const attList = detail.querySelector('#attList');\n    if (attList) {\n      (m.attachments || []).forEach(a => {\n        const item = document.createElement('div');\n        item.className = 'att-item';\n        const url = 'data:' + a.mimeType + ';base64,' + a.data;\n        if ((a.mimeType || '').indexOf('image/') === 0) {\n          const img = document.createElement('img');\n          img.className = 'att-img';\n          img.src = url;\n          img.alt = a.filename || '';\n          item.appendChild(img);\n        } else if ((a.mimeType || '').indexOf('video/') === 0) {\n          const v = document.createElement('video');\n          v.className = 'att-video';\n          v.controls = true;\n          v.preload = 'metadata';\n          v.src = url;\n          item.appendChild(v);\n        }\n        const name = document.createElement('div');\n        name.className = 'att-name';\n        name.textContent = a.filename || '附件';\n        const meta = document.createElement('div');\n        meta.className = 'att-meta';\n        meta.textContent = fmtSize(a.size);\n        const link = document.createElement('a');\n        link.className = 'att-link';\n        link.href = url;\n        link.download = a.filename || 'attachment';\n        link.textContent = '下载';\n        item.appendChild(name);\n        item.appendChild(meta);\n        item.appendChild(link);\n        attList.appendChild(item);\n      });\n    }\n    const skipList = detail.querySelector('#skipList');\n    if (skipList) {\n      (m.skippedAttachments || []).forEach(a => {\n        const item = document.createElement('div');\n        item.className = 'att-item';\n        const name = document.createElement('div');\n        name.className = 'att-name';\n        name.textContent = a.filename || '附件';\n        const meta = document.createElement('div');\n        meta.className = 'att-meta';\n        meta.textContent = fmtSize(a.size) + ' · ' + (a.reason || '未保存');\n        item.appendChild(name);\n        item.appendChild(meta);\n        skipList.appendChild(item);\n      });\n    }\n    detail.querySelectorAll('.code-chip').forEach(el => {\n      el.onclick = async () => {\n        const ok = await copyText(el.dataset.code, '验证码已复制');\n        if (ok) {\n          const small = el.querySelector('small');\n          if (small) {\n            const orig = small.textContent;\n            small.textContent = '已复制 ✓';\n            setTimeout(() => { small.textContent = orig; }, 1500);\n          }\n        }\n      };\n    });\n    detail.querySelector('#delMsgBtn').onclick = async () => {\n      try {\n        await api('/api/mailboxes/' + encodeURIComponent(b.address) + '/messages/' + id + '?token=' + encodeURIComponent(b.token), { method: 'DELETE' });\n        detail.innerHTML = '';\n        loadMessages();\n      } catch (e) { setStatus('删除失败：' + e.message, 'error'); }\n    };\n    detail.scrollIntoView({ behavior: 'smooth', block: 'nearest' });\n  } catch (e) {\n    detail.innerHTML = '<div class=\"detail\"><div class=\"status error\">读取失败：' + e.message + '</div></div>';\n  }\n}\n\nasync function copyText(text, okMsg) {\n  // 1) 现代 Clipboard API（HTTPS 下可用）\n  if (navigator.clipboard && navigator.clipboard.writeText) {\n    try {\n      await navigator.clipboard.writeText(text);\n      setStatus(okMsg || '已复制', 'ok');\n      return true;\n    } catch (_) { /* 掉到备用方案 */ }\n  }\n  // 2) 备用方案：临时输入框 + 选中 + execCommand。\n  // 手机上必须 focus + setSelectionRange，否则 select() 经常选不中；\n  // execCommand 返回 false 表示没复制上，不能像以前那样一律报成功。\n  try {\n    const ta = document.createElement('textarea');\n    ta.value = text;\n    ta.setAttribute('readonly', '');\n    ta.style.position = 'fixed';\n    ta.style.top = '0';\n    ta.style.left = '0';\n    ta.style.opacity = '0';\n    document.body.appendChild(ta);\n    ta.focus();\n    ta.setSelectionRange(0, ta.value.length);\n    const ok = document.execCommand('copy');\n    document.body.removeChild(ta);\n    if (ok) { setStatus(okMsg || '已复制', 'ok'); return true; }\n  } catch (_) { /* 掉到失败提示 */ }\n  setStatus('复制失败：请长按验证码，手动选择复制', 'error');\n  return false;\n}\n\nlet pollMs = POLL_MS;\nfunction restartPolling(ms) {\n  if (pollTimer) clearInterval(pollTimer);\n  pollMs = ms;\n  pollTimer = setInterval(() => { if (!document.hidden) loadMessages(); }, ms);\n}\n\nfunction startPolling() {\n  restartPolling(POLL_MS);\n  if (countdownTimer) clearInterval(countdownTimer);\n  countdownTimer = setInterval(() => { renderExpiry(); renderBoxList(); }, 30000);\n}\n\n// 版本检查：页面一直开着时，后台更新后提醒用户刷新（否则新功能看不到）\nconst LOADED_VERSION = '1.0.8';\nasync function checkUpdate() {\n  try {\n    const r = await fetch('/health');\n    const h = await r.json();\n    if (h.version && h.version !== LOADED_VERSION) {\n      $('updateBanner').style.display = 'block';\n    }\n  } catch (_) {}\n}\n$('updateReloadBtn').onclick = () => location.reload();\nsetInterval(checkUpdate, 60000);\ncheckUpdate();\n\n$('ttlRow').addEventListener('click', ev => {\n  const btn = ev.target.closest('.ttl-btn');\n  if (!btn) return;\n  selectedTtl = btn.dataset.ttl;\n  document.querySelectorAll('.ttl-btn').forEach(x => x.classList.toggle('active', x === btn));\n});\n$('genBtn').onclick = generateMailbox;\n$('refreshBtn').onclick = () => { setStatus('正在刷新…'); loadMessages().then(() => setStatus('')); };\n$('selectAllBtn').onclick = () => {\n  if (lastMessages.length > 0 && selectedIds.size === lastMessages.length) {\n    selectedIds = new Set();\n  } else {\n    selectedIds = new Set(lastMessages.map(m => m.id));\n  }\n  renderMessages(lastMessages);\n};\n$('delSelectedBtn').onclick = async () => {\n  const b = currentBox();\n  const ids = [...selectedIds];\n  if (!b || !ids.length) return;\n  if (!confirm('确定删除选中的 ' + ids.length + ' 封邮件吗？')) return;\n  try {\n    const res = await api('/api/mailboxes/' + encodeURIComponent(b.address) + '/messages?token=' + encodeURIComponent(b.token), {\n      method: 'DELETE',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ ids }),\n    });\n    selectedIds = new Set();\n    $('detail').innerHTML = '';\n    setStatus('已删除 ' + (res && res.deleted !== undefined ? res.deleted : ids.length) + ' 封邮件', 'ok');\n    loadMessages();\n  } catch (e) { setStatus('删除失败：' + e.message, 'error'); }\n};\n$('copyBtn').onclick = () => { const b = currentBox(); if (b) copyText(b.address, '邮箱已复制'); };\n$('delBoxBtn').onclick = async () => {\n  const b = currentBox();\n  if (!b) return;\n  if (!confirm('确定删除 ' + b.address + ' 吗？里面的邮件会一起删掉。')) return;\n  try {\n    await api('/api/mailboxes/' + encodeURIComponent(b.address) + '?token=' + encodeURIComponent(b.token), { method: 'DELETE' });\n  } catch (e) { /* 服务端删失败也继续从列表移除 */ }\n  removeBox(b.address, false);\n  setStatus('邮箱已删除', 'ok');\n};\ndocument.addEventListener('visibilitychange', () => { if (!document.hidden) loadMessages(); });\n\n// 启动：恢复保存的邮箱，没有就自动生成一个\n(async () => {\n  boxes = loadBoxes();\n  if (boxes.length) {\n    current = boxes[0].address;\n    renderAll();\n    startPolling();\n    loadMessages();\n  } else {\n    renderAll();\n    startPolling();\n    generateMailbox();\n  }\n})();\n</script>\n</body>\n</html>\n";

function json(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' },
  });
}

function randomStr(len, chars) {
  const arr = new Uint8Array(len);
  crypto.getRandomValues(arr);
  let out = '';
  for (let i = 0; i < len; i++) out += chars[arr[i] % chars.length];
  return out;
}
const randomUsername = () => randomStr(10, 'abcdefghijklmnopqrstuvwxyz0123456789');
const randomToken = () => randomStr(32, 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789');
const randomMsgId = () => randomStr(16, '0123456789abcdef');

const isExpired = mb => !!(mb && mb.expiresAt && Date.now() > mb.expiresAt);

// 解码 RFC 2047 编码字，如 =?UTF-8?B?5rWL6K+V6YKu5Lu2?= → 测试邮件。
// 支持 B（base64）和 Q（quoted-printable）两种编码；相邻编码字之间的空白按规范忽略；
// 解不出的字符集回退到 UTF-8，实在解不了就原样返回，不影响收件。
function decodeRfc2047(str) {
  if (!str || str.indexOf('=?') === -1) return str;
  const cleaned = str.replace(/(\?=\s+)(?==\?)/g, '?=');
  return cleaned.replace(/=\?([^?\s]+)\?([bBqQ])\?([^?]*)\?=/g, (m, charset, enc, text) => {
    let bytes;
    try {
      if (enc.toUpperCase() === 'B') {
        const bin = atob(text.replace(/\s/g, ''));
        bytes = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      } else {
        const q = text.replace(/_/g, ' ');
        const arr = [];
        for (let i = 0; i < q.length; i++) {
          if (q[i] === '=' && /^[0-9A-Fa-f]{2}$/.test(q.slice(i + 1, i + 3))) {
            arr.push(parseInt(q.slice(i + 1, i + 3), 16));
            i += 2;
          } else {
            arr.push(q.charCodeAt(i));
          }
        }
        bytes = new Uint8Array(arr);
      }
      try {
        return new TextDecoder(charset).decode(bytes);
      } catch (_) {
        return new TextDecoder('utf-8').decode(bytes);
      }
    } catch (_) {
      return m;
    }
  });
}
// ArrayBuffer → base64（分块转换，避免大文件爆栈）
function arrayBufferToBase64(buf) {
  const bytes = new Uint8Array(buf);
  let bin = '';
  const CHUNK = 8192;
  for (let i = 0; i < bytes.length; i += CHUNK) {
    bin += String.fromCharCode.apply(null, bytes.subarray(i, i + CHUNK));
  }
  return btoa(bin);
}
// 剩余寿命（秒），用于 KV 自动过期；永久返回 null
function remainingTtl(mb) {
  if (!mb || !mb.expiresAt) return null;
  return Math.max(60, Math.floor((mb.expiresAt - Date.now()) / 1000));
}

function kv(env) {
  if (!env || !env.MAILBOXES) throw new Error('KV 未绑定：请在 Worker 设置里绑定名为 MAILBOXES 的 KV');
  return env.MAILBOXES;
}

// KV 写重试：同一 key 短时间内连续写会触发 429 限流（比如连续删邮件时反复写索引），
// 退避重试几次一般就能过；不是 429 的错误直接抛出。
async function kvPutRetry(store, key, value, opts) {
  let delay = 300;
  for (let attempt = 0; attempt < 4; attempt++) {
    try {
      await store.put(key, value, opts);
      return;
    } catch (e) {
      const msg = String((e && e.message) || '');
      if (attempt < 3 && (msg.includes('429') || msg.toLowerCase().includes('too many'))) {
        await new Promise(r => setTimeout(r, delay));
        delay *= 2;
        continue;
      }
      throw e;
    }
  }
}

async function getMailbox(env, address) {
  return kv(env).get('mb:' + address, 'json');
}

async function deleteMailbox(env, address) {
  const store = kv(env);
  await store.delete('mb:' + address);
  await store.delete('idx:' + address);
  let cursor;
  do {
    const page = await store.list({ prefix: 'msg:' + address + ':', cursor });
    for (const k of page.keys) await store.delete(k.name);
    cursor = page.list_complete ? null : page.cursor;
  } while (cursor);
}

// 校验邮箱存在 + token 正确 + 未过期；失败返回 {error, status}
async function authMailbox(env, address, token) {
  const mb = await getMailbox(env, address);
  if (!mb) return { error: '邮箱不存在', status: 404 };
  if (isExpired(mb)) {
    // 懒清理：过期邮箱读到就删掉
    await deleteMailbox(env, address).catch(() => {});
    return { error: '邮箱已过期', status: 410 };
  }
  if (!token || token !== mb.token) return { error: 'token 不正确', status: 403 };
  return { mb };
}

async function handleFetch(request, env) {
  const url = new URL(request.url);
  const p = url.pathname;

  if (p === '/health') {
    return json({ ok: true, version: WORKER_VERSION, domain: MAIL_DOMAIN, time: new Date().toISOString() });
  }

  // ---- 创建邮箱 ----
  if (p === '/api/mailboxes' && request.method === 'POST') {
    const body = await request.json().catch(() => ({}));
    const ttlKey = typeof body.ttl === 'string' && body.ttl in TTL_OPTIONS ? body.ttl : '1h';
    const ttlSec = TTL_OPTIONS[ttlKey];
    // 每 IP 限流
    const ip = request.headers.get('CF-Connecting-IP') || 'unknown';
    const hour = Math.floor(Date.now() / 3600000);
    const rlKey = 'rl:' + ip + ':' + hour;
    const store = kv(env);
    const used = parseInt(await store.get(rlKey)) || 0;
    if (used >= CREATE_LIMIT_PER_HOUR) {
      return json({ error: '创建太频繁，请稍后再试' }, 429);
    }
    const now = Date.now();
    const address = randomUsername() + '@' + MAIL_DOMAIN;
    const mb = {
      address,
      token: randomToken(),
      createdAt: now,
      expiresAt: ttlSec > 0 ? now + ttlSec * 1000 : null,
    };
    const opts = ttlSec > 0 ? { expirationTtl: ttlSec } : undefined;
    await kvPutRetry(store, 'mb:' + address, JSON.stringify(mb), opts);
    await kvPutRetry(store, rlKey, String(used + 1), { expirationTtl: 3600 });
    return json(mb, 201);
  }

  // ---- /api/mailboxes/:address[/messages[/:id]] ----
  const m = p.match(/^\/api\/mailboxes\/([^/]+)(?:\/messages(?:\/([^/]+))?)?$/);
  if (m) {
    const address = decodeURIComponent(m[1]).toLowerCase();
    const msgId = m[2] ? decodeURIComponent(m[2]) : null;
    const user = address.split('@')[0];
    if (!ADDRESS_RE.test(user) || !address.endsWith('@' + MAIL_DOMAIN)) {
      return json({ error: '邮箱地址不正确' }, 400);
    }
    if (msgId && !MSG_ID_RE.test(msgId)) {
      return json({ error: '邮件 ID 不正确' }, 400);
    }
    const token = url.searchParams.get('token') || '';
    const isMsgRoute = p.includes('/messages');

    if (!isMsgRoute && request.method === 'GET') {
      const auth = await authMailbox(env, address, token);
      if (auth.error) return json({ error: auth.error }, auth.status);
      const idx = (await kv(env).get('idx:' + address, 'json')) || [];
      return json({ address, createdAt: auth.mb.createdAt, expiresAt: auth.mb.expiresAt, messageCount: idx.length });
    }
    if (!isMsgRoute && request.method === 'DELETE') {
      const auth = await authMailbox(env, address, token);
      if (auth.error) return json({ error: auth.error }, auth.status);
      await deleteMailbox(env, address);
      return new Response(null, { status: 204 });
    }
    if (isMsgRoute && !msgId && request.method === 'GET') {
      const auth = await authMailbox(env, address, token);
      if (auth.error) return json({ error: auth.error }, auth.status);
      const idx = (await kv(env).get('idx:' + address, 'json')) || [];
      return json({ messages: idx, expiresAt: auth.mb.expiresAt });
    }
    if (isMsgRoute && msgId && request.method === 'GET') {
      const auth = await authMailbox(env, address, token);
      if (auth.error) return json({ error: auth.error }, auth.status);
      const msg = await kv(env).get('msg:' + address + ':' + msgId, 'json');
      if (!msg) return json({ error: '邮件不存在' }, 404);
      return json(msg);
    }
    if (isMsgRoute && msgId && request.method === 'DELETE') {
      const auth = await authMailbox(env, address, token);
      if (auth.error) return json({ error: auth.error }, auth.status);
      await kv(env).delete('msg:' + address + ':' + msgId);
      const idx = ((await kv(env).get('idx:' + address, 'json')) || []).filter(x => x.id !== msgId);
      const ttl = remainingTtl(auth.mb);
      await kvPutRetry(kv(env), 'idx:' + address, JSON.stringify(idx), ttl ? { expirationTtl: ttl } : undefined);
      return new Response(null, { status: 204 });
    }
    // 批量删除：DELETE /messages，body {ids:[...]} 删选中的，不带 ids 删全部。
    // 索引只写一次，避免连续删邮件时反复写同一 key 触发 KV 429。
    if (isMsgRoute && !msgId && request.method === 'DELETE') {
      const auth = await authMailbox(env, address, token);
      if (auth.error) return json({ error: auth.error }, auth.status);
      const body = await request.json().catch(() => ({}));
      const ids = Array.isArray(body.ids) ? body.ids.filter(id => typeof id === 'string' && MSG_ID_RE.test(id)) : null;
      const idx = (await kv(env).get('idx:' + address, 'json')) || [];
      const targetIds = ids === null ? idx.map(x => x.id) : idx.filter(x => ids.includes(x.id)).map(x => x.id);
      for (let i = 0; i < targetIds.length; i += 10) {
        await Promise.all(targetIds.slice(i, i + 10).map(id => kv(env).delete('msg:' + address + ':' + id)));
      }
      const rest = ids === null ? [] : idx.filter(x => !ids.includes(x.id));
      if (rest.length === 0) {
        await kv(env).delete('idx:' + address);
      } else {
        const ttl = remainingTtl(auth.mb);
        await kvPutRetry(kv(env), 'idx:' + address, JSON.stringify(rest), ttl ? { expirationTtl: ttl } : undefined);
      }
      return json({ deleted: targetIds.length, remaining: rest.length });
    }
    return json({ error: '未知接口' }, 404);
  }

  if (p.startsWith('/api/')) {
    return json({ error: '未知接口' }, 404);
  }

  // ---- 前端页面（单文件内嵌，其他路径也回退到首页）----
  return new Response(INDEX_HTML, {
    headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' },
  });
}

// ---- 收件：Email Routing catch-all 转发到这里 ----
// 只收“已生成且未过期”的邮箱的邮件，其他一律拒收（防止域名变成公开垃圾箱）。
async function handleEmail(message, env) {
  const to = (message.to || '').toLowerCase().trim();
  if (!to.endsWith('@' + MAIL_DOMAIN)) {
    message.setReject('Unknown domain');
    return;
  }
  const store = kv(env);
  const mb = await store.get('mb:' + to, 'json');
  if (!mb) {
    message.setReject('No such mailbox');
    return;
  }
  if (isExpired(mb)) {
    await deleteMailbox(env, to).catch(() => {});
    message.setReject('Mailbox expired');
    return;
  }
  const idx = (await store.get('idx:' + to, 'json')) || [];
  if (idx.length >= MAX_MSGS_PER_BOX) {
    message.setReject('Mailbox full');
    return;
  }
  // 解析正文：message.raw 是单次读取的流，读一次交给 PostalMime 解析；
  // 解析失败也不拒收，只存空正文（标题/发件人照常入库）。
  let text = '';
  let html = '';
  let parsedSubject = '';
  let parsedFrom = null;
  let attachments = [];
  let skippedAttachments = [];
  try {
    const buf = await new Response(message.raw).arrayBuffer();
    const parsed = await PostalMime.parse(buf, { attachmentEncoding: 'base64' });
    text = (parsed.text || '').slice(0, MAX_TEXT_CHARS);
    html = (parsed.html || '').slice(0, MAX_HTML_CHARS);
    parsedSubject = parsed.subject || '';
    parsedFrom = parsed.from || null;
    let totalSize = 0;
    for (const a of (parsed.attachments || [])) {
      const name = a.filename || '附件';
      const mime = a.mimeType || 'application/octet-stream';
      let data;
      let size;
      if (typeof a.content === 'string') {
        data = a.content;
        const b64 = a.content.replace(/\s/g, '');
        const pad = b64.endsWith('==') ? 2 : (b64.endsWith('=') ? 1 : 0);
        size = Math.floor(b64.length * 3 / 4) - pad;
      } else if (a.content && a.content.byteLength !== undefined) {
        size = a.content.byteLength;
        data = arrayBufferToBase64(a.content);
      } else {
        continue;
      }
      if (size > MAX_ATTACHMENT_BYTES || totalSize + size > MAX_ATTACHMENTS_TOTAL) {
        skippedAttachments.push({ filename: name, mimeType: mime, size, reason: '文件太大，未保存' });
        continue;
      }
      totalSize += size;
      attachments.push({ filename: name, mimeType: mime, size, data });
    }
  } catch (e) {
    console.error('mime parse error:', e);
  }
  let from = message.from || '';
  if (parsedFrom) {
    const f = Array.isArray(parsedFrom) ? parsedFrom[0] : parsedFrom;
    if (f && f.address) from = f.name ? f.name + ' <' + f.address + '>' : f.address;
  }
  from = decodeRfc2047(from);
  let subject = parsedSubject;
  if (!subject) {
    try { subject = decodeRfc2047(message.headers.get('subject') || ''); } catch (_) {}
  } else {
    subject = decodeRfc2047(subject);
  }
  const id = randomMsgId();
  const createdAt = Date.now();
  const snippet = text.replace(/\s+/g, ' ').trim().slice(0, 120);
  const ttl = remainingTtl(mb);
  const opts = ttl ? { expirationTtl: ttl } : undefined;
  await kvPutRetry(store, 'msg:' + to + ':' + id, JSON.stringify({ id, from, subject, createdAt, text, html, attachments, skippedAttachments }), opts);
  idx.unshift({ id, from, subject, createdAt, snippet });
  await kvPutRetry(store, 'idx:' + to, JSON.stringify(idx), opts);
}

// ---- 定时清理：每小时删掉过期的邮箱（KV TTL 是主力清理，这里是兜底）----
async function handleScheduled(event, env) {
  const store = kv(env);
  let cursor;
  let deleted = 0;
  do {
    const page = await store.list({ prefix: 'mb:', cursor });
    for (const k of page.keys) {
      const mb = await store.get(k.name, 'json');
      if (mb && isExpired(mb)) {
        await deleteMailbox(env, mb.address).catch(() => {});
        deleted++;
      }
    }
    cursor = page.list_complete ? null : page.cursor;
  } while (cursor);
  console.log('cleanup: deleted ' + deleted + ' expired mailboxes');
}

export default {
  async fetch(request, env, ctx) {
    try {
      return await handleFetch(request, env, ctx);
    } catch (e) {
      console.error('fetch error:', e);
      return json({ error: e.message || '服务器内部错误' }, 500);
    }
  },
  async email(message, env, ctx) {
    try {
      await handleEmail(message, env);
    } catch (e) {
      console.error('email error:', e);
      try { message.setReject('Temporary error'); } catch (_) {}
    }
  },
  async scheduled(event, env, ctx) {
    ctx.waitUntil(handleScheduled(event, env).catch(e => console.error('scheduled error:', e)));
  },
};
